/* @autogenerated */
package net.civeira.phylax.feature.observe.viewer;

import java.util.List;
import java.util.Map;
import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.exception.NotFoundException;
import net.civeira.phylax.feature.observe.issue.IssueAliases;
import net.civeira.phylax.feature.observe.issue.IssueTracker;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.ObservedFingerprintRule;
import net.civeira.phylax.feature.observe.observedfingerprintrule.domain.gateway.ObservedFingerprintRuleCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssue;
import net.civeira.phylax.feature.observe.observedissue.domain.ObservedIssueStatusOptions;
import net.civeira.phylax.feature.observe.observedissue.domain.gateway.ObservedIssueCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedissuealias.domain.gateway.ObservedIssueAliasCommandRepositoryGateway;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.ObservedIssueComment;
import net.civeira.phylax.feature.observe.observedissuecomment.domain.gateway.ObservedIssueCommentCommandRepositoryGateway;

/** The actions of the viewer on the issues: assign, snooze, comment, ticket, split and merge. */
class ObserveIssueWorkflowUnitTest {
  private ObservedIssueCommandRepositoryGateway issues;
  private ObservedIssueAliasCommandRepositoryGateway aliases;
  private ObservedIssueCommentCommandRepositoryGateway comments;
  private ObservedFingerprintRuleCommandRepositoryGateway rules;
  private IssueAliases registry;
  private IssueTracker tracker;
  private ObserveIssueWorkflow workflow;
  private ObservedIssue issue;

  @BeforeEach
  void setUp() {
    issues = Mockito.mock(ObservedIssueCommandRepositoryGateway.class);
    aliases = Mockito.mock(ObservedIssueAliasCommandRepositoryGateway.class);
    comments = Mockito.mock(ObservedIssueCommentCommandRepositoryGateway.class);
    rules = Mockito.mock(ObservedFingerprintRuleCommandRepositoryGateway.class);
    registry = Mockito.mock(IssueAliases.class);
    tracker = Mockito.mock(IssueTracker.class);
    workflow = new ObserveIssueWorkflow(issues, aliases, comments, rules, registry, tracker);
    issue = Mockito.mock(ObservedIssue.class);
    Mockito.when(issue.getTitle()).thenReturn("NullPointerException in checkout");
    Mockito.when(issue.getCount()).thenReturn(7);
    Mockito.when(issue.getOriginUid()).thenReturn("source-uid");
    Mockito.when(issue.getTrackerUrl()).thenReturn(Optional.empty());
    Mockito.when(issue.getCulprit()).thenReturn(Optional.of("Checkout.pay"));
    Mockito.when(issue.getRelease()).thenReturn(Optional.of("1.2"));
    Mockito.when(issues.find(Mockito.any())).thenReturn(Optional.of(issue));
  }

  @Test
  @DisplayName("An unknown issue is not found")
  void unknown() {
    Mockito.when(issues.find(Mockito.any())).thenReturn(Optional.empty());
    Assertions.assertThrows(NotFoundException.class, () -> workflow.assign("missing", "alice"));
    Assertions.assertThrows(NotFoundException.class,
        () -> workflow.comment("missing", "alice", "hi"));
  }

  @Test
  @DisplayName("An issue is assigned and unassigned")
  void assign() {
    Assertions.assertEquals(Map.of("assignee", "alice"), workflow.assign("issue", "alice"));
    Mockito.verify(issue).assign("alice", "alice");
    Assertions.assertEquals(Map.of("assignee", ""), workflow.assign("issue", null));
    Mockito.verify(issue).assign("", "");
    Mockito.verify(issues, Mockito.times(2)).update(Mockito.eq(issue), Mockito.any());
  }

  @Test
  @DisplayName("A snooze lasts some hours or some more events, or nothing when empty")
  void snooze() {
    Map<String, Object> both = workflow.snooze("issue", 2, 10);
    Assertions.assertNotNull(both.get("until"));
    Assertions.assertEquals(17, both.get("untilCount"), "The limit counts from the current events");

    Map<String, Object> none = workflow.snooze("issue", 0, null);
    Assertions.assertNull(none.get("until"));
    Assertions.assertNull(none.get("untilCount"));
    Mockito.verify(issue).snooze(null, null);
  }

  @Test
  @DisplayName("A comment needs a text and is cut to its maximum length")
  void comment() {
    Assertions.assertThrows(IllegalArgumentException.class,
        () -> workflow.comment("issue", "alice", " "));
    Assertions.assertThrows(IllegalArgumentException.class,
        () -> workflow.comment("issue", "alice", null));
    Mockito.when(comments.create(Mockito.any()))
        .thenAnswer(invocation -> invocation.getArgument(0));

    ObserveIssueWorkflow.CommentRow row = workflow.comment("issue", "alice", "x".repeat(12_000));
    Assertions.assertEquals("alice", row.author());
    Assertions.assertEquals(10_000, row.text().length());
  }

  @Test
  @DisplayName("The comments are listed from the oldest")
  void comments() {
    ObservedIssueComment older = Mockito.mock(ObservedIssueComment.class);
    ObservedIssueComment newer = Mockito.mock(ObservedIssueComment.class);
    java.time.OffsetDateTime now = java.time.OffsetDateTime.now();
    Mockito.when(older.getCreatedAt()).thenReturn(now.minusHours(1));
    Mockito.when(older.getText()).thenReturn("first");
    Mockito.when(newer.getCreatedAt()).thenReturn(now);
    Mockito.when(newer.getText()).thenReturn("second");
    Mockito.when(comments.list(Mockito.any())).thenReturn(List.of(newer, older));

    Assertions.assertEquals(List.of("first", "second"),
        workflow.comments("issue").stream().map(ObserveIssueWorkflow.CommentRow::text).toList());
  }

  @Test
  @DisplayName("A ticket is created once on the tracker and then reused")
  void ticket() {
    Mockito.when(tracker.create(Mockito.anyString(), Mockito.anyString()))
        .thenReturn("https://tracker/1");

    Assertions.assertEquals(Map.of("url", "https://tracker/1"),
        workflow.ticket("issue", "https://viewer/i"));
    Mockito.verify(tracker).create(Mockito.eq("NullPointerException in checkout"),
        Mockito.argThat(text -> text.contains("Culprit: Checkout.pay") && text.contains("Events: 7")
            && text.contains("Release: 1.2") && text.contains("https://viewer/i")));
    Mockito.verify(issue).linkTicket("https://tracker/1");

    Mockito.when(issue.getTrackerUrl()).thenReturn(Optional.of("https://tracker/1"));
    Assertions.assertEquals(Map.of("url", "https://tracker/1"),
        workflow.ticket("issue", "https://viewer/i"));
    Mockito.verify(tracker, Mockito.times(1)).create(Mockito.anyString(), Mockito.anyString());
  }

  @Test
  @DisplayName("A split creates a grouping rule only with a safe pattern")
  void split() {
    Assertions.assertThrows(IllegalArgumentException.class,
        () -> workflow.split("issue", "x".repeat(300), "too long"));
    Mockito.when(rules.create(Mockito.any())).thenAnswer(invocation -> invocation.getArgument(0));

    Map<String, Object> result = workflow.split("issue", "timeout after \\d+ ms", null);
    Assertions.assertNotNull(result.get("rule"));
    Mockito.verify(rules).create(
        Mockito.argThat((ObservedFingerprintRule rule) -> rule.getName().startsWith("Split of ")));
  }

  @Test
  @DisplayName("An issue can not be merged into itself nor into a merged one")
  void merge_rules() {
    Assertions.assertThrows(IllegalArgumentException.class, () -> workflow.merge("issue", "issue"));
    Mockito.when(issue.getStatus()).thenReturn(ObservedIssueStatusOptions.MERGED);
    Assertions.assertThrows(IllegalArgumentException.class, () -> workflow.merge("one", "other"));
    Mockito.verifyNoInteractions(aliases, registry);
  }
}
